values ('36da85a9-90fc-59b6-ae28-c3222d577eed', '3055b4cb-ea01-56fa-8abb-c33e127a781d', 1, 'Soften the onion in olive oil for 5 minutes, then add half the garlic for 30 seconds.', 'شوّح البصل في زيت الزيتون ٥ دقايق، وبعدين ضيف نص التوم ٣٠ ثانية.', 6, null, null, '{"onions","olive oil","garlic"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('d8c9c419-86df-5c81-af73-f28bd3137dd4', '3055b4cb-ea01-56fa-8abb-c33e127a781d', 2, 'Add the blended tomato, paste and salt. Simmer 10 minutes until it darkens.', 'ضيف الطماطم المضروبة والصلصة والملح. سيبها ١٠ دقايق لحد ما لونها يغمق.', 10, null, null, '{"tomatoes","tomato paste","salt"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('70cf25e9-baae-5e54-b03a-cd599cecf993', '3055b4cb-ea01-56fa-8abb-c33e127a781d', 3, 'Add the okra whole and simmer 18 minutes without stirring much — stirring is what makes it slimy.', 'ضيف البامية صحيحة وسيبها ١٨ دقيقة من غير تقليب كتير — التقليب هو اللي بيخلّيها متلزّجة.', 18, null, null, '{"okra"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('3f2f8ce9-e8a1-5608-a6a7-3669da33c99d', '3055b4cb-ea01-56fa-8abb-c33e127a781d', 4, 'Fry the rest of the garlic with the coriander and tip it in. Finish with lemon.', 'حمّر باقي التوم مع الكزبرة وكبّها فوق. زيّن بالليمون.', 3, null, null, '{"garlic","coriander","lemon"}');

