values ('88ab97d4-3e1b-50eb-a949-c4a26128bd9b', '8d48fde4-3c56-5c70-9fbf-4f479897f01e', (select id from public.ingredients where slug = 'honey' limit 1), 'honey', 'honey', 2, 'tbsp', null, true, false, false, null, 3);
