values ('e40f5bb2-1c09-5578-8bdf-cecb2e812393', 'cdfd6850-f006-57fb-8657-4e46345be2d1', 1, 'Fry the hollowed potatoes briefly in oil so they hold their shape, then set aside.', 'اقلي البطاطس المفرّغة شوية في الزيت عشان تحافظ على شكلها، وبعدين ارفعها.', 10, null, null, '{"potatoes","vegetable oil"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('f070e16d-f478-57e1-9f38-bbc0838eb79f', 'cdfd6850-f006-57fb-8657-4e46345be2d1', 2, 'Cook the onion and mince with the spice until browned, then stuff the potatoes.', 'اطبخ البصل واللحمة مع البهارات لحد ما تتحمّر، وبعدين احشي البطاطس.', 12, 'Ground beef must reach 71°C / 160°F all the way through.', 'اللحمة المفرومة لازم توصل ٧١°م / ١٦٠°ف من جواها لبره.', '{"onions","ground beef","mixed spice"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('bdc14f2a-6744-52a9-89c5-54cb8719224a', 'cdfd6850-f006-57fb-8657-4e46345be2d1', 3, 'Make the sauce from the tomatoes, paste, garlic and salt, and pour it round the potatoes.', 'اعمل الصلصة من الطماطم والصلصة والتوم والملح، وصبّها حوالين البطاطس.', 5, null, null, '{"tomatoes","tomato paste","garlic","salt"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('712f0c5a-73df-5709-a77c-f602c1445dd3', 'cdfd6850-f006-57fb-8657-4e46345be2d1', 4, 'Bake covered at 190°C for 35 minutes, then uncovered for 10 more.', 'اخبزها مغطّاة على ١٩٠ درجة ٣٥ دقيقة، وبعدين مكشوفة ١٠ كمان.', 45, null, null, '{}');

