values ('fa0ee885-a49b-5756-a6a3-043778b21087', '9d4ee2dd-68bd-5927-b993-b9f224c54a6a', 1, 'Scramble the eggs quickly in hot oil and lift them out.', 'اعمل البيض سكرامبل بسرعة في زيت سخن وارفعه.', 3, null, null, '{"eggs","vegetable oil"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('3f8063d6-ff8a-524b-ac4f-582937053da9', '9d4ee2dd-68bd-5927-b993-b9f224c54a6a', 2, 'Sear the chicken hard until browned and cooked through, then set aside.', 'شوّح الفراخ كويس لحد ما تتحمّر وتستوي، وبعدين ارفعها.', 6, 'Poultry must reach 74°C / 165°F throughout.', 'الفراخ لازم توصل ٧٤°م / ١٦٥°ف في كل مكان فيها.', '{"chicken breast"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('1b0d848d-2c20-556a-a866-8fb5516c29c0', '9d4ee2dd-68bd-5927-b993-b9f224c54a6a', 3, 'Stir-fry the carrot, peas and garlic for 3 minutes, then add the cold rice and fry hard.', 'شوّح الجزر والبسلة والتوم ٣ دقايق، وبعدين ضيف الرز البارد واقليه على نار عالية.', 6, 'Only use rice that was cooled quickly and refrigerated, and reheat it once until piping hot.', 'استخدم بس رز اتبرّد بسرعة واتحط في التلاجة، وسخّنه مرة واحدة بس لحد ما يبقى سخن جدًا.', '{"carrots","green peas","garlic","rice"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('af564686-137f-54a2-a4e9-6a4cf26e412e', '9d4ee2dd-68bd-5927-b993-b9f224c54a6a', 4, 'Return everything, add soy and sesame oil, and finish with green onion.', 'رجّع كل حاجة، ضيف الصويا وزيت السمسم، وزيّن بالبصل الأخضر.', 3, null, null, '{"soy sauce","sesame oil","green onion"}');

