values ('5635f9e1-4f0e-5665-97aa-a27a3b73f0e6', '1e4a6fbe-f6c1-5b67-873d-aa19c2ff0ff1', (select id from public.ingredients where slug = 'butter' limit 1), 'butter', 'butter', 30, 'g', null, true, false, false, null, 2);
