values ('a90eef57-83cc-5277-af22-1a57a7584071', 'e8a2237f-2003-5dcf-b874-46c58bd2653f', 2, 'Split each bread and pack the filling in a thin, even layer right to the edges.', 'افتح كل رغيف واحشيه طبقة رفيعة متساوية لحد الأطراف.', 5, null, null, '{"baladi bread"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('9293e1a3-e694-5ef8-b28e-2259c95db0dd', 'e8a2237f-2003-5dcf-b874-46c58bd2653f', 3, 'Bake at 220°C for 25 minutes, turning once, until the bread is crisp and the meat is done.', 'اخبزه على ٢٢٠ درجة ٢٥ دقيقة مع تقليبه مرة، لحد ما العيش يقرمش واللحمة تستوي.', 25, 'Ground beef must reach 71°C / 160°F all the way through.', 'اللحمة المفرومة لازم توصل ٧١°م / ١٦٠°ف من جواها لبره.', '{}');

