values ('fb9e7515-f940-57f7-96fa-ce83cd0c9ad5', '68a203cd-a645-59b8-8893-89e7146fb152', 2, 'Fry the onion and garlic, add the mince and brown it, then the tomatoes, paste and cumin.', 'حمّر البصل والتوم، ضيف اللحمة وحمّرها، وبعدين الطماطم والصلصة والكمون.', 12, 'Ground beef must reach 71°C / 160°F all the way through.', 'اللحمة المفرومة لازم توصل ٧١°م / ١٦٠°ف من جواها لبره.', '{"onions","garlic","ground beef","tomatoes","tomato paste","cumin"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('c7c4e59a-d6b0-5833-81b8-964453e029e5', '68a203cd-a645-59b8-8893-89e7146fb152', 3, 'Layer eggplant and sauce in a dish, finish with the pepper strips.', 'رصّ الباذنجان والصلصة في صينية، وزيّن بشرايح الفلفل.', 5, null, null, '{"bell pepper"}');
