values ('71eb25d4-5eb9-5150-b454-fd950a06abc2', 'b9e7b782-0d05-58ec-af6b-7b9b594e7125', 2, 'Stir-fry the carrot and peas for 3 minutes, then add the garlic for 30 seconds.', 'شوّح الجزر والبسلة ٣ دقايق، وبعدين ضيف التوم ٣٠ ثانية.', 4, null, null, '{"carrots","green peas","garlic"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('6be171af-508e-505d-98bc-57eb10c242c0', 'b9e7b782-0d05-58ec-af6b-7b9b594e7125', 3, 'Add the cold rice, breaking up clumps, and fry hard for 4 minutes until it starts to catch.', 'ضيف الرز البارد وفكّك التكتّلات، واقليه على نار عالية ٤ دقايق لحد ما يبدأ يتحمّر.', 4, 'Only use rice that was cooled quickly and refrigerated, and reheat it once until piping hot.', 'استخدم بس رز اتبرّد بسرعة واتحط في التلاجة، وسخّنه مرة واحدة بس لحد ما يبقى سخن جدًا.', '{"rice"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('30bdea92-e348-5720-bb93-35e8a7b73d82', 'b9e7b782-0d05-58ec-af6b-7b9b594e7125', 4, 'Fold the egg back in with the green onions and season.', 'رجّع البيض مع البصل الأخضر وظبّط الملح.', 1, null, null, '{"green onion"}');

