values ('b2f09d36-3560-5c76-ac01-37e41251b5ad', 'e69f8c48-4437-5751-90f0-c2a1090d2239', 1, 'Make a soft dough with flour, yeast, salt, oil and 300ml warm water and let it rise 75 minutes.', 'اعجن عجينة طرية من الدقيق والخميرة والملح والزيت و٣٠٠ مل مية دافية وسيبها تخمر ٧٥ دقيقة.', 80, null, null, '{"flour","yeast","salt","olive oil"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('ed4dcfb8-f5bb-5447-b3ea-ecacf9b67919', 'e69f8c48-4437-5751-90f0-c2a1090d2239', 2, 'Mix the raw lamb with the onion, tomato, molasses and spice.', 'اخلط اللحمة النية مع البصل والطماطم والدبس والبهارات.', 8, 'Wash hands and surfaces after handling raw mince, and keep it away from anything eaten raw.', 'اغسل إيديك والأسطح بعد ما تلمس لحمة مفرومة نية، وابعدها عن أي حاجة هتتاكل نية.', '{"lamb","onions","tomatoes","pomegranate molasses","mixed spice"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
