values ('09b06abe-e44d-5137-8cd8-6d5f67238900', 'bf470081-5b5f-5785-bf51-4be091959a52', 2, 'Rest the paste 15 minutes, then shape into flat discs and press sesame seeds onto one side.', 'سيب العجينة ترتاح ١٥ دقيقة، وبعدين شكّلها أقراص مفلطحة واضغط السمسم على وش واحد.', 15, null, null, '{"sesame seeds"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('708ea0e1-a1d9-5625-aee0-572031fe4ecc', 'bf470081-5b5f-5785-bf51-4be091959a52', 3, 'Fry in hot oil for 3 minutes a side until deep brown. Drain on paper.', 'اقليها في زيت سخن ٣ دقايق لكل وش لحد ما تبقى بنّي غامق. صفّيها على ورق.', 8, 'Hot oil spits. Lower each piece in with a spoon rather than dropping it.', 'الزيت السخن بينطّ. نزّل كل قطعة بمعلقة بدل ما ترميها.', '{"vegetable oil"}');

